-- Issue #57 (ADR 0001): the SecretStore's table. Each row is one AES-256-GCM sealed value;
-- the plaintext and the master key (STUDIO_SECRETS_KEY) never reach the database. The id is
-- the opaque reference business tables hold; it is generated by the API, not by PostgreSQL,
-- because it is bound to the ciphertext as additional authenticated data before the insert.
-- key_version names the master key that sealed the row, so a later rotation needs no data
-- migration. No business table gains a secret column.

-- CreateTable
CREATE TABLE "secrets" (
    "id" UUID NOT NULL,
    "ciphertext" BYTEA NOT NULL,
    "nonce" BYTEA NOT NULL,
    "auth_tag" BYTEA NOT NULL,
    "key_version" INTEGER NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT now(),

    CONSTRAINT "secrets_pkey" PRIMARY KEY ("id")
);

-- Defence in depth on the shape of the sealed parts (the adapter also fails closed on them).
-- Prisma does not model CHECK constraints, so they live only here, and schema diffs ignore them.
ALTER TABLE "secrets" ADD CONSTRAINT "secrets_nonce_length_check" CHECK (octet_length("nonce") = 12);
ALTER TABLE "secrets" ADD CONSTRAINT "secrets_auth_tag_length_check" CHECK (octet_length("auth_tag") = 16);
ALTER TABLE "secrets" ADD CONSTRAINT "secrets_key_version_check" CHECK ("key_version" >= 1);
